// 临时验证脚本：验证列表响应格式错误时显示加载失败而非空列表。
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import puppeteer from 'puppeteer-core';

const repoRoot = import.meta.dirname;
const serverBin = path.join(repoRoot, 'score-arena');
const dataDir = await mkdtemp(path.join(tmpdir(), 'sa-verify-'));

const proc = spawn(serverBin, ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
  { stdio: ['ignore', 'pipe', 'inherit'] });
const baseURL = await new Promise((resolve, reject) => {
  let buf = '';
  proc.stdout.on('data', (c) => {
    buf += c.toString();
    const m = buf.match(/listening on (http:\/\/\S+)/);
    if (m) resolve(m[1]);
  });
  proc.on('exit', (code) => reject(new Error('server exited ' + code)));
});

const browser = await puppeteer.launch({
  executablePath: process.env.CHROME_PATH || '/usr/bin/google-chrome',
  headless: true,
  args: ['--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage'],
});

const ERROR_TEXT = '房间列表加载失败，请稍后刷新重试。已有数据不会因此丢失。';
let failures = 0;
function check(name, cond) {
  if (cond) { console.log('PASS', name); }
  else { failures++; console.log('FAIL', name); }
}

// 每个用例：拦截首次 GET /api/rooms 返回指定正文，之后放行。
async function loadWithFirstGet(body) {
  const page = await browser.newPage();
  let intercepted = 0;
  let posts = 0;
  await page.setRequestInterception(true);
  page.on('request', (req) => {
    if (req.method() === 'POST' && req.url().endsWith('/api/rooms')) posts++;
    if (req.method() === 'GET' && req.url().endsWith('/api/rooms') && intercepted === 0) {
      intercepted++;
      req.respond({ status: 200, contentType: 'application/json; charset=utf-8', body });
    } else {
      req.continue();
    }
  });
  await page.goto(baseURL + '/', { waitUntil: 'networkidle0' });
  await page.waitForFunction(
    () => document.querySelector('#list-area .list-error') ||
          document.querySelector('#list-area .empty') ||
          document.querySelector('#list-area table') ||
          document.querySelector('#list-area .skip-notice'),
    { timeout: 5000 });
  return { page, getPosts: () => posts };
}

async function listState(page) {
  return page.evaluate(() => {
    const area = document.getElementById('list-area');
    return {
      error: (area.querySelector('.list-error') || {}).textContent || null,
      empty: (area.querySelector('.empty') || {}).textContent || null,
      rows: area.querySelectorAll('tbody tr').length,
      html: area.innerHTML,
    };
  });
}

// 1. 各类错误格式 → 加载失败提示，且无空列表提示、无表格
const badBodies = [
  ['顶层 null', 'null'],
  ['顶层数组', '[{"id":"x"}]'],
  ['顶层字符串', '"rooms"'],
  ['顶层数字', '42'],
  ['顶层布尔', 'true'],
  ['缺少 rooms', '{"total":3}'],
  ['rooms 为 null', '{"rooms":null}'],
  ['rooms 为对象', '{"rooms":{"a":1}}'],
  ['rooms 为字符串', '{"rooms":"[]"}'],
  ['rooms 为数字', '{"rooms":0}'],
  ['空对象', '{}'],
];
for (const [name, body] of badBodies) {
  const { page } = await loadWithFirstGet(body);
  const s = await listState(page);
  check('错误格式显示加载失败: ' + name,
    s.error === ERROR_TEXT && s.empty === null && s.rows === 0);
  await page.close();
}

// 2. 合法形态：空数组 → 空提示；带附加字段的对象 → 正常读取
{
  const { page } = await loadWithFirstGet('{"rooms":[]}');
  const s = await listState(page);
  check('rooms 空数组显示空提示', s.empty === '还没有房间记录。' && s.error === null);
  await page.close();
}
{
  const { page } = await loadWithFirstGet(
    '{"rooms":[{"id":"r1","name":"测试","game":"ludo","capacity":3,"turnSeconds":30,"status":"waiting"}],"extra":{"page":1}}');
  const s = await listState(page);
  check('带附加字段的有效响应正常展示', s.rows === 1 && s.error === null && s.empty === null);
  await page.close();
}

// 3. 错误格式后再次正常读取 → 失败提示被正常结果替换
{
  const { page } = await loadWithFirstGet('{"rooms":null}');
  let s = await listState(page);
  check('首次错误格式显示失败', s.error === ERROR_TEXT);
  await page.evaluate(() => location.reload());
  await page.waitForFunction(
    () => document.querySelector('#list-area table') || document.querySelector('#list-area .empty'),
    { timeout: 5000 });
  s = await listState(page);
  check('后续正常读取替换失败提示', s.error === null);
  await page.close();
}

// 4. 创建成功 + 刷新拿到错误格式：成功提示与编号保留、按钮恢复、不重发创建
{
  const { page, getPosts } = await loadWithFirstGet('{"rooms":[]}');
  // 拦截紧随创建的 GET 刷新，返回错误格式
  await page.evaluate(() => {
    const origFetch = window.fetch;
    window.__getCount = 0;
    window.fetch = function (url, opts) {
      if (!opts && String(url).includes('/api/rooms')) {
        window.__getCount++;
        return Promise.resolve(new Response('{"rooms":"oops"}',
          { status: 200, headers: { 'Content-Type': 'application/json' } }));
      }
      return origFetch.apply(this, arguments);
    };
  });
  await page.type('#name', '验证房间');
  await page.select('#game', 'gomoku');
  await page.type('#turnSeconds', '0');
  await page.click('#submit');
  await page.waitForFunction(
    () => document.querySelector('#list-area .list-error') &&
          document.getElementById('form-msg').classList.contains('ok'),
    { timeout: 5000 });
  const msg = await page.evaluate(() => document.getElementById('form-msg').textContent);
  const btnDisabled = await page.evaluate(() => document.getElementById('submit').disabled);
  const s = await listState(page);
  check('创建成功提示与编号保留', /房间已创建，编号：\S+/.test(msg));
  check('创建后刷新格式错误显示加载失败', s.error === ERROR_TEXT && s.empty === null);
  check('处理结束后创建按钮恢复可用', btnDisabled === false);
  await new Promise((r) => setTimeout(r, 300));
  check('未再次发送创建请求', getPosts() === 1);
  check('未声称房间没有保存', !msg.includes('没有保存') && !msg.includes('未保存'));
  await page.close();
}

await browser.close();
proc.kill('SIGKILL');
await rm(dataDir, { recursive: true, force: true });
console.log(failures === 0 ? 'ALL PASS' : failures + ' FAILURES');
process.exit(failures === 0 ? 0 : 1);

